const { chromium } = require('playwright');
const TARGET_URL = 'http://localhost:8765';
const OUT = '/private/tmp/claude-501/-Users-chiragnvijay-Desktop-Projects-unite-hack-DataMining-Hack/5cd5e0d0-e7f3-45bd-a832-ed2352a27f70/scratchpad';

const pct = async (page, prefix) => {
  const out = {};
  for (const k of ['complaints', 'breadth', 'requests', 'survey']) out[k] = Number(await page.locator(`#${prefix}-${k}`).inputValue());
  return out;
};
const total = (p) => Object.values(p).reduce((a, b) => a + b, 0);

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 60 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  const bodies = [];
  page.on('request', (r) => { if (r.url().includes('/api/agent/evaluate')) bodies.push(JSON.parse(r.postData())); });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  try {
    await page.goto(TARGET_URL);
    await page.locator('form input').first().fill('make seat massage standard on the 5 Series in Europe');
    await page.locator('form button[type=submit]').click();
    await page.getByText('Signal weights', { exact: false }).first().waitFor({ timeout: 60000 });
    console.log('Weights question visible; sliders hidden by default:', await page.locator('#sw-complaints').count() === 0);
    await page.screenshot({ path: `${OUT}/1-question.png` });

    await page.getByRole('radio', { name: /Yes, adjust the weights/ }).click();
    console.log('Opened sliders:', await pct(page, 'sw'));
    await page.locator('#sw-complaints').fill('60');
    let p = await pct(page, 'sw'); console.log('Complaints -> 60:', p, 'total', total(p));
    await page.locator('#sw-survey').fill('100');
    p = await pct(page, 'sw'); console.log('Survey -> 100:', p, 'total', total(p));
    await page.locator('#sw-survey').fill('25');
    p = await pct(page, 'sw'); console.log('Survey -> 25:', p, 'total', total(p));
    await page.locator('#sw-breadth').fill('50');
    p = await pct(page, 'sw'); console.log('Breadth -> 50:', p, 'total', total(p));
    await page.screenshot({ path: `${OUT}/2-sliders.png` });

    await page.getByRole('button', { name: /Check against the data/ }).click();
    await page.waitForFunction(() => document.body.innerText.includes('Adjust the decision policy') || document.body.innerText.includes('Hide the decision policy'), null, { timeout: 60000 }).catch(() => {});
    const sent = bodies.at(-1)?.policy?.weights;
    console.log('Weights sent to /api/agent/evaluate:', sent, 'sum', sent && Object.values(sent).reduce((a, b) => a + b, 0));

    // engine step: the policy panel must show the same weights
    await page.getByText('Score against the data').first().click();
    const btn = page.getByRole('button', { name: /Adjust the decision policy/ });
    await btn.waitFor({ timeout: 30000 });
    await btn.click();
    const pp = await pct(page, 'pw'); console.log('Policy panel shows:', pp, 'total', total(pp));
    await page.locator('#pw-requests').fill('0');
    await page.waitForTimeout(1200);   // debounced engine re-run
    const pp2 = await pct(page, 'pw'); console.log('Policy panel requests -> 0:', pp2, 'total', total(pp2));
    const sent2 = bodies.at(-1)?.policy?.weights;
    console.log('Re-run sent:', sent2, 'sum', sent2 && Object.values(sent2).reduce((a, b) => a + b, 0), '; requests so far:', bodies.length);
    await page.screenshot({ path: `${OUT}/3-policy.png` });

    // back to the choose step: "No, use the defaults" resets
    await page.getByText('Choose what to check', { exact: false }).first().click().catch(() => {});
    const no = page.getByRole('radio', { name: /No, use the defaults/ });
    if (await no.count()) {
      await no.click();
      console.log('After "No, use the defaults": sliders hidden =', await page.locator('#sw-complaints').count() === 0,
        '; pending note =', await page.getByText('Run the check again to apply').count());
      await page.screenshot({ path: `${OUT}/4-defaults.png` });
    } else console.log('Could not reopen the choose step');
    console.log('Page errors:', errors.length ? errors : 'none');
  } catch (e) {
    console.error('FAILED:', e.message);
    await page.screenshot({ path: `${OUT}/fail.png` });
  } finally {
    await browser.close();
  }
})();

